import java.util.Scanner;

public class Main {
    static class InputData {
        long m;
        int n, m_;
        boolean read(Scanner sc) {
            if (sc.hasNextInt()) {
                n = sc.nextInt();
                if (sc.hasNextInt()) {
                    m_ = sc.nextInt();
                    if (sc.hasNextLong()) {
                        m = sc.nextLong();
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static class OutputData extends InputData {
        long answer;
        void print() {
            System.out.println(answer);
        }
    }

    static class Solution {
        long m;
        int n, m_;
        long[][] comb;
        Pair[] seq;
        Pair[][] dp;

        static class Pair {
            long first, second;
            Pair(long first, long second) {
                this.first = first;
                this.second = second;
            }
        }

        long pow_mod(long base, long exp) {
            long res = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) res = res * base % m;
                base = base * base % m;
                exp >>= 1;
            }
            return res;
        }

        long mod_inv(long x) {
            return pow_mod(x, m - 2);
        }

        void compute() {
            comb = new long[n + 1][n + 1];
            for (int i = 0; i <= n; ++i) {
                for (int j = 0; j <= n; ++j) {
                    if (i == 0 || j == 0) {
                        comb[i][j] = 1;
                    } else {
                        comb[i][j] = (comb[i - 1][j] + comb[i][j - 1]) % m;
                    }
                }
            }

            seq = new Pair[m_ + 1];
            for (int i = 0; i <= m_; ++i) {
                seq[i] = new Pair(0, 0);
            }
            seq[0] = new Pair(1, 0);
            for (int i = 1; i <= m_; ++i) {
                for (int j = 0; j < i; ++j) {
                    Pair cur = new Pair(0, 0);
                    cur.first = seq[j].first * seq[i - 1 - j].first % m;
                    cur.second = (seq[j].second * seq[i - 1 - j].first + seq[j].first * seq[i - 1 - j].second) % m;
                    long ss_j = 0; // placeholder for ss(j), assuming ss(j) = 0 as not defined
                    long ss_i_j = 0; // placeholder for ss(i - 1 - j)
                    cur.second = (cur.second * (i + 1) + (ss_j + ss_i_j) * cur.first) % m;
                    cur.first = cur.first * (i + 1) % m;
                    cur.first = cur.first * comb[j][i - 1 - j] % m;
                    cur.second = cur.second * comb[j][i - 1 - j] % m;
                    seq[i].first = (seq[i].first + cur.first) % m;
                    seq[i].second = (seq[i].second + cur.second) % m;
                }
            }

            dp = new Pair[n + 2][m_ + 1];
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m_; ++j) {
                    dp[i][j] = new Pair(0, 0);
                }
            }
            dp[0][0] = new Pair(1, 0);
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m_; ++j) {
                    for (int k = 0; k <= Math.min(n - i, m_ - j); ++k) {
                        Pair cur = new Pair(0, 0);
                        cur.first = seq[k].first * dp[i][j].first % m;
                        cur.second = (seq[k].second * dp[i][j].first + seq[k].first * dp[i][j].second) % m;
                        cur.first = cur.first * comb[j][k] % m;
                        cur.second = cur.second * comb[j][k] % m;
                        int ni = i + k + 1;
                        int nj = j + k;
                        dp[ni][nj].first = (dp[ni][nj].first + cur.first) % m;
                        dp[ni][nj].second = (dp[ni][nj].second + cur.second) % m;
                    }
                }
            }
            answer = dp[n + 1][m_].second;
        }

        void reset() {
            // No specific reset needed in Java
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        InputData input = new InputData();
        OutputData output = new OutputData();

        if (System.getenv("SG") != null) {
            while (input.read(sc)) {
                output.n = input.n;
                output.m_ = input.m_;
                output.m = input.m;
                Solution sol = new Solution();
                sol.n = input.n;
                sol.m_ = input.m_;
                sol.m = input.m;
                sol.compute();
                output.answer = sol.answer;
                output.print();
                sol.reset();
            }
        } else {
            if (input.read(sc)) {
                Solution sol = new Solution();
                sol.n = input.n;
                sol.m_ = input.m_;
                sol.m = input.m;
                sol.compute();
                output.answer = sol.answer;
                output.print();
            }
        }
        sc.close();
    }
}
